// Dados extraídos de APLICAÇÃO_DE_INSUMOS.xlsx (aba 'APLICAÇÃO INSUMOS', linha 2 = cabeçalho,
// dados a partir da linha 3) em 2026-08-07, já com:
// - correção pontual da linha 707 (SAFRA '25/27' -> '25/26', erro de digitação confirmado)
// - numAplicacaoTextoOriginal preenchido quando a coluna NUM. APLICAÇÃO da planilha tinha
//   texto em vez de número (ex: 'DESSECAÇÃO', 'POS COLHEITA', 'ETHREL' — 60 linhas ao todo).
//   Nesses casos numAplicacao já vem com o fallback 1, e o texto original é usado para
//   compor a observacao do registro no banco (ver route.ts).
// areaPorTalhao e produtoLookup vêm da aba 'Planilha1' (Tabela2 e Tabela3), usados como
// fallback de área/preço só quando a própria linha não tiver o valor.
// Gerado uma única vez para a importação real via rota admin — não é recalculado em runtime.

export interface LinhaPlanilha {
  linha: number
  talhao: string
  area: number | null
  atividade: string | null
  produto: string
  unidade: string
  valorUnitario: number | null
  qtd: number | null
  numBombas: number | null
  totalQtd: number | null
  data: string | null
  numAplicacao: number
  numAplicacaoTextoOriginal: string | null
  safraRaw: string
}

